    'lesson.pillars-islam.title': 'İslam\'ın Şartları',
    'lesson.pillars-islam.summary': 'Dinin üzerine kurulduğu beş esas',
    'lesson.pillars-faith.title': 'İmanın Şartları',
    'lesson.pillars-faith.summary': 'Cibril hadisinde geçen altı esas',
    'lesson.ihsan.title': 'İhsan',
